CREATE TABLE IF NOT EXISTS usuarios(id SERIAL PRIMARY KEY,nombre VARCHAR(120) NOT NULL,usuario VARCHAR(60) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,rol VARCHAR(20) NOT NULL DEFAULT 'OPERADOR',activo BOOLEAN DEFAULT TRUE,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS combustibles(id SERIAL PRIMARY KEY,codigo VARCHAR(30) UNIQUE NOT NULL,nombre VARCHAR(60) NOT NULL,precio_referencia NUMERIC(12,2) NOT NULL DEFAULT 0,unidad VARCHAR(20) NOT NULL DEFAULT 'GALÓN',activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS vehiculos(id SERIAL PRIMARY KEY,placa VARCHAR(15) UNIQUE NOT NULL,marca VARCHAR(60),modelo VARCHAR(60),anio INT,tipo VARCHAR(40),combustible VARCHAR(30),activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS conductores(id SERIAL PRIMARY KEY,nombre VARCHAR(120) UNIQUE NOT NULL,documento VARCHAR(30),telefono VARCHAR(30),activo BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS abastecimientos(id SERIAL PRIMARY KEY,vehiculo_id INT NOT NULL REFERENCES vehiculos(id),conductor_id INT NOT NULL REFERENCES conductores(id),fecha DATE NOT NULL,hora TIME,km_anterior NUMERIC(12,2) DEFAULT 0,km_actual NUMERIC(12,2) NOT NULL,recorrido NUMERIC(12,2) DEFAULT 0,combustible VARCHAR(30) NOT NULL,galones NUMERIC(12,3) NOT NULL,precio_galon NUMERIC(12,2) NOT NULL,importe NUMERIC(12,2) NOT NULL,consumo NUMERIC(12,2) DEFAULT 0,n_factura VARCHAR(60),n_ticket VARCHAR(60),n_boleta VARCHAR(60),descripcion TEXT,creado_por INT REFERENCES usuarios(id),creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_abast_fecha ON abastecimientos(fecha);
CREATE INDEX IF NOT EXISTS idx_abast_vehiculo ON abastecimientos(vehiculo_id);
CREATE INDEX IF NOT EXISTS idx_abast_combustible ON abastecimientos(combustible);
CREATE UNIQUE INDEX IF NOT EXISTS ux_abast_ticket ON abastecimientos(n_ticket) WHERE n_ticket IS NOT NULL AND n_ticket <> '';
